The specification is written straight from the docstring. `post` accepts `result` only when it is an integer `d` with `1 <= d < n` that divides `n`, and no larger integer below `n` also divides `n`. It finds the expected answer with its own loop and compares it to `result`, without relying on the function's search bound.

```python
def pre(n):
    return 2 <= n and n <= 120


def expected_largest_proper_divisor(n):
    # Search downward from n-1 and stop at the first divisor of n.
    best = 1
    found = False
    for d in range(n - 1, 0, -1):
        if not found:
            if n % d == 0:
                best = d
                found = True
    return best


def post(n, result):
    # The result must be an integer, not a bool.
    if result is None:
        return False
    if result is True or result is False:
        return False

    # It must lie in the range 1 <= result < n.
    # This is checked before n % result, which would fail for result == 0.
    if result < 1:
        return False
    if result >= n:
        return False

    # It must divide n exactly.
    if n % result != 0:
        return False

    # No larger d < n may also divide n.
    for d in range(result + 1, n):
        if n % d == 0:
            return False

    # Cross-check against the independently computed answer.
    return result == expected_largest_proper_divisor(n)
